fn ext(p: { ...s }, q: { ...t }): { ...s, ...t } where s disjoint t =
  ext(p, q);

fn use(): Int = {
  let f = fn(x, y) => ext(x, y).a;
  let shown = show(1 + 2);
  if shown == "3" then 1 else 2
};

fn later(n: Int): Int = n + 1;

fn bad(): Int = {
  let x = later(1, 2);
  x + 1
};

